custom_css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Plus+Jakarta+Sans:wght@600&family=Poppins:wght@500&display=swap');

:root {
    --white: #fff;
    --black: #111;
    --body: #474747;
    --heading: #1c1c1c;
    --pink: #e01783;
    --blue: #00758d;
    --purple: #773dbe;
    --dark: #161a29;
    --light: #f6f6f6;
    --font-body: Inter, Arial, sans-serif;
    --font-heading: 'Plus Jakarta Sans', Arial, sans-serif;
    --container: 1200px;
    --radius: 12px
}

* {
    box-sizing: border-box
}

html {
    scroll-behavior: smooth
}

body {
    margin: 0;
    color: var(--body);
    font: 400 16px/1.75 var(--font-body);
    background: var(--white)
}

img {
    display: block;
    max-width: 100%
}

a {
    text-decoration: none
}

button {
    font: inherit
}

.container {
    width: min(var(--container), calc(100% - 40px));
    margin-inline: auto
}

.section-padding {
    padding: 80px 0
}

.bg-white {
    background: var(--white)
}

.bg-light {
    background: var(--light)
}

.section-dark {
    background: var(--dark);
    color: var(--white);
    overflow: hidden;
    position: relative
}

.section-dark:before,
.section-dark:after {
    content: "";
    position: absolute;
    border-radius: 50%;
    filter: blur(50px);
    pointer-events: none
}

.section-dark:before {
    width: 400px;
    height: 400px;
    background: rgba(119, 61, 190, .12);
    left: -70px;
    top: -70px
}

.section-dark:after {
    width: 600px;
    height: 600px;
    background: rgba(224, 23, 131, .12);
    right: 2%;
    top: 0
}

.section-dark>.container {
    position: relative;
    z-index: 1
}

.txt-pink {
    color: var(--pink)
}

h1,
h2,
h3 {
    font-family: var(--font-heading);
    color: var(--heading);
    margin: 0
}

h1 {
    font-size: clamp(30px, 4vw, 55px) !important;
    line-height: 1.16;
    font-weight: 500
}

h2 {
    font-size: clamp(24px, 3vw, 40px) !important;
    line-height: 1.25;
    font-weight: 500
}

h3 {
    font-size: 24px !important;
    line-height: 1.65;
    font-weight: 600
}

.section-dark h1,
.section-dark h2,
.section-dark h3 {
    color: var(--white)
}

p {
    margin: 0
}

.eyebrow {
    font-size: 18px;
    line-height: 1.5;
    font-weight: 500;
    margin-bottom: 12px
}

.theme-btn {
    display: inline-flex;
    align-items: center;
    justify-content: flex-end;
    gap: 12px;
    min-height: 50px;
    padding: 7px 7px 7px 20px;
    border-radius: var(--radius);
    color: #fff;
    font-weight: 500;
    line-height: 1.2
}

.theme-btn span {
    width: 36px;
    height: 36px;
    background: #fff;
    border-radius: 12px;
    display: grid;
    place-items: center;
    flex: 0 0 auto
}

.theme-btn span img {
    width: 36px;
    height: 36px;
    margin: 0;
}

.theme-btn-blue {
    background: var(--blue)
}

.theme-btn-purple {
    background: var(--purple)
}

.section-heading {
    margin-bottom: 38px
}

.section-heading h2 {
    display: inline-block
}

.section-heading img {
    width: 155px;
    height: 18px;
    object-fit: contain;
    margin: 0 auto
}

.section-heading.left img {
    margin-left: 240px;
    width: 135px
}

.hero {
    padding: 80px 0
}

.hero-content {
    max-width: 694px
}

.hero-subtitle {
    font-size: 20px;
    line-height: 1.6;
    margin-top: 24px
}

.hero-quote {
    line-height: 2;
    max-width: 588px;
    margin-top: 8px
}

.button-row {
    margin-top: 24px
}

.hero-image img {
    width: 100%;
    max-width: 527px;
    margin-left: auto
}

.trust-strip {
    background: var(--blue);
    color: #fff;
    padding: 40px 0;
    position: relative;
    overflow: hidden
}

.trust-strip::after {
    content: "";
    position: absolute;
    width: 115px;
    height: 94px;
    right: 0;
    top: 50%;
    transform: translateY(-50%);
    background: url('https://res.cloudinary.com/cgibjxmm/image/upload/v1785916237/custom-cms/trust-strip-flower.png') center/contain no-repeat;
    opacity: .08;
    pointer-events: none
}

.trust-strip .container {
    position: relative;
    z-index: 1
}

.trust-item {
    display: flex;
    align-items: center;
    gap: 15px;
    font-size: 20px;
    line-height: 1.4
}

.trust-icon img {
    width: 44px;
    height: 44px
}

.service-card {
    position: relative;
    background: #fff;
    border-radius: var(--radius);
    box-shadow: 0 0 4px rgba(0, 0, 0, .25);
    padding: 8px 8px 12px;
    min-height: 400px
}

.service-image {
    height: 180px;
    border-radius: var(--radius);
    overflow: hidden
}

.service-image img {
    width: 100%;
    height: 100%;
    object-fit: cover
}

.service-icon {
    width: 50px;
    height: 50px;
    display: flex;
    margin: -25px 0 0 12px;
}

.service-icon img {
    width: 50px;
    height: 50px;
    position: relative;
    z-index: 1
}

.service-content {
    padding: 2px 12px 0
}

.service-content h3 {
    font-family: var(--font-body);
    font-size: 20px;
    line-height: 1.6;
    font-weight: 500;
    color: #333
}

.service-content p {
    color: #333;
    line-height: 2;
    min-height: 96px
}

.service-content a {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    color: var(--blue);
    font-weight: 500;
    line-height: 2;
    margin-top: 8px
}

.service-content a .service-link-arrow {
    width: 24px;
    height: 24px;
    flex: 0 0 auto
}

.decorative-right {
    position: relative;
    overflow: hidden
}

.decorative-right:after,
.decorative-right-top:after {
    content: "";
    position: absolute;
    width: 415px;
    height: 415px;
    background: url('https://res.cloudinary.com/cgibjxmm/image/upload/v1785916241/custom-cms/yoga-girl-background.png') center/contain no-repeat;
    right: 0;
    bottom: 0;
    pointer-events: none
}

.arts-story .container {
    position: relative;
    z-index: 1
}

.story-image {
    position: relative;
    border-radius: var(--radius);
    overflow: hidden;
    margin: 0
}

.story-image img {
    width: 100%;
    height: 492px;
    object-fit: cover
}

.story-image figcaption {
    position: absolute;
    bottom: 4px;
    left: 0;
    right: 0;
    text-align: center;
    color: #fff;
    font-size: 12px
}

.story-title {
    margin-bottom: 20px
}

.arts-story h3 {
    margin-bottom: 12px
}

.arts-story p {
    line-height: 1.75;
    margin-bottom: 32px
}

.about-image {
    border-radius: var(--radius);
    overflow: hidden
}

.about-image img {
    width: 100%;
    height: 296px;
    object-fit: cover
}

.about-copy p {
    line-height: 1.75;
    margin: 22px 0 30px
}

.quote-card {
    margin: 0;
    background: var(--blue);
    border-radius: var(--radius);
    height: 296px;
    padding: 80px 30px 20px;
    position: relative;
    overflow: hidden
}

.quote-card p {
    font-size: 20px;
    line-height: 1.6;
    font-weight: 500
}

.quote-card cite {
    display: block;
    margin-top: 18px
}

.quote-mark {
    position: absolute;
    left: 20px;
    top: 10px;
    width: 60px;
    height: 60px
}

.quote-art {
    position: absolute;
    right: 15px;
    bottom: 15px;
    width: 97px;
    height: 191px;
}

.decorative-left {
    position: relative;
    overflow: hidden
}

.decorative-left:before {
    content: "";
    position: absolute;
    width: 400px;
    height: 414px;
    left: 0;
    top: 0;
    background: url('https://res.cloudinary.com/cgibjxmm/image/upload/v1785916220/custom-cms/hosting-event-background.png') center/contain no-repeat;
}

.events .container {
    position: relative;
    z-index: 1
}

.events h2 {
    margin-bottom: 40px
}

.event-image {
    border-radius: var(--radius);
    overflow: hidden
}

.event-image img {
    width: 100%;
    height: 341px;
    object-fit: cover
}

.demand h2 {
    margin-bottom: 24px
}

.check-list {
    list-style: none;
    margin: 0 0 32px;
    padding: 0;
    display: grid;
    gap: 20px
}

.check-list li {
    font-size: 20px;
    font-weight: 500;
    display: flex;
    align-items: center;
    gap: 12px
}

.check-list li:before {
    content: "";
    width: 24px;
    height: 24px;
    background: url('https://res.cloudinary.com/cgibjxmm/image/upload/v1785921454/custom-cms/blue-checklist.png') center/contain no-repeat;
    flex: none
}

.devices {
    position: relative;
    min-height: 396px
}

.devices .laptop {
    width: 692px;
    margin-left: auto
}

.devices .phone {
    position: absolute;
    left: 0;
    bottom: 0;
    width: 158px;
    z-index: 2
}

.faqs {
    padding-bottom: 80px
}

.accordion {
    display: grid;
    gap: 12px
}

.faq-item {
    background: var(--light);
    border-radius: var(--radius);
    overflow: hidden
}

.faq-item.active {
    background: #fff;
    box-shadow: 0 0 4px rgba(0, 0, 0, .25)
}

.faq-question {
    width: 100%;
    border: 0;
    background: transparent;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    padding: 20px 20px 20px 40px;
    color: var(--heading);
    font-weight: 500;
    font-size: 20px;
    text-align: left;
    cursor: pointer
}

.faq-question img {
    width: 40px;
    height: 40px;
    flex: none
}

.faq-answer {
    display: none;
    padding: 0 40px 30px;
    max-width: 900px;
    line-height: 1.75
}

.faq-item.active .faq-answer {
    display: block
}

.media-grid figure {
    margin: 0;
    text-align: center
}

.media-grid img,
.media-grid iframe {
    display: block;
    width: 100%;
    aspect-ratio: 16/9;
    object-fit: cover;
    border: 0;
    border-radius: var(--radius)
}

.media-grid figcaption {
    font-size: 24px;
    line-height: 1.65;
    font-weight: 500;
    color: var(--heading);
    margin-top: 10px
}

.certifications {
    overflow: hidden;
    position: relative
}

.decorative-right-top:after {
    opacity: .12;
    top: 0;
    bottom: auto
}

.cert-track {
    display: flex;
    align-items: center;
    gap: 80px;
    width: max-content;
    transform: translateX(-110px);
    position: relative;
    z-index: 1
}

.cert-track img {
    width: 200px;
    height: 200px;
    object-fit: contain;
    flex: none
}

.about.section-dark::before {
    width: 600px;
    height: 600px;
    left: -114px;
    top: -220px;
    background: rgba(224, 23, 131, .12);
}

.about.section-dark::after {
    width: 400px;
    height: 400px;
    left: 52.4%;
    right: auto;
    top: 122px;
    background: rgba(119, 61, 190, .12);
}

.certifications.decorative-right-top::after {
    width: 400px;
    height: 414px;
    top: 0;
    right: 0;
    bottom: auto;
    background-image: url('https://res.cloudinary.com/cgibjxmm/image/upload/v1785916220/custom-cms/hosting-event-background.png');
    opacity: 1;
    transform: none;
}

.cert-marquee {
    width: 100%;
    overflow: hidden;
    position: relative;
    z-index: 1;
}

.cert-track {
    display: flex;
    align-items: center;
    gap: 0;
    width: max-content;
    margin-left: -110px;
    transform: none;
    animation: certification-scroll 32s linear infinite;
    will-change: transform;
}

.cert-group {
    display: flex;
    align-items: center;
    gap: 80px;
    padding-right: 80px;
    flex: 0 0 auto;
}

.cert-group img {
    width: 200px;
    height: 200px;
    object-fit: contain;
    flex: 0 0 auto;
}

@keyframes certification-scroll {
    from {
        transform: translate3d(0, 0, 0);
    }

    to {
        transform: translate3d(-50%, 0, 0);
    }
}

@media(max-width:1023px) {
    .section-padding {
        padding: 64px 0
    }

    .hero {
        padding: 64px 0
    }

    .hero-image img {
        margin: 0 auto
    }

    .trust-strip {
        padding: 30px 0
    }

    .arts-story .container {
        grid-template-columns: 1fr
    }

    .story-image {
        max-width: 650px
    }

    .about .container {
        grid-template-columns: 1fr 1fr
    }

    .quote-card {
        grid-column: 1/-1;
        height: auto;
        min-height: 260px
    }

    .events .container,
    .demand .container {
        grid-template-columns: 1fr
    }

    .devices {
        max-width: 760px;
        width: 100%;
        margin: auto
    }

    .service-content p {
        min-height: 0
    }

    .section-heading.left img {
        margin-left: 210px
    }

    .cert-track {
        gap: 45px
    }

    .cert-track img {
        width: 160px;
        height: 160px
    }
    .cert-track {
        margin-left: -70px;
    }

    .cert-group {
        gap: 45px;
        padding-right: 45px;
    }

    .cert-group img {
        width: 160px;
        height: 160px;
    }
}

@media(max-width:767px) {
    .container {
        width: min(100% - 30px, var(--container))
    }

    .section-padding {
        padding: 50px 0
    }

    .hero {
        padding: 50px 0
    }

    .hero-content {
        text-align: left
    }

    .hero-image {
        margin-top: 12px
    }

    .hero-subtitle {
        margin-top: 18px
    }

    .button-row {
        gap: 12px
    }

    .theme-btn {
        width: auto
    }

    .trust-item {
        font-size: 16px
    }

    .trust-icon {
        width: 44px;
        height: 44px
    }

    .service-grid {
        gap: 18px
    }

    .story-image img {
        height: auto
    }

    .arts-story br {
        display: none
    }

    .about .container {
        grid-template-columns: 1fr
    }

    .quote-card {
        grid-column: auto
    }

    .about-copy p {
        margin: 16px 0 24px
    }

    .event-image img {
        height: auto
    }

    .devices {
        min-height: 260px
    }

    .devices .laptop {
        width: 82%
    }

    .devices .phone {
        width: 22%
    }

    .section-heading.left img {
        margin-left: 170px
    }

    .faq-question {
        font-size: 17px;
        padding: 14px 12px 14px 18px
    }

    .faq-question img {
        width: 36px;
        height: 36px
    }

    .faq-answer {
        padding: 0 18px 22px
    }

    .media-grid figcaption {
        font-size: 20px
    }

    .cert-track {
        gap: 25px;
        transform: translateX(-45px)
    }

    .cert-track img {
        width: 130px;
        height: 130px
    }

    .cert-track {
        margin-left: -45px;
        animation-duration: 24s;
    }

    .cert-group {
        gap: 25px;
        padding-right: 25px;
    }

    .cert-group img {
        width: 130px;
        height: 130px;
    }

    .decorative-right::after,
    .certifications.decorative-right-top::after {
        width: 280px;
        height: 280px;
        background-size: contain;
    }

    .events.decorative-left::before {
        width: 280px;
        height: 290px;
        background-size: contain;
    }
}

@media(max-width:479px) {
    h1 {
        font-size: 38px
    }

    .section-heading.left img {
        margin-left: 120px;
        width: 110px
    }

    .theme-btn {
        font-size: 14px
    }

    .trust-strip .container {
        gap: 18px
    }

    .service-card {
        min-height: auto
    }

    .quote-card {
        padding: 70px 22px 24px
    }

    .quote-card p {
        font-size: 18px
    }

    .devices {
        min-height: 190px
    }

    .cert-track img {
        width: 110px;
        height: 110px
    }

    .cert-group img {
        width: 110px;
        height: 110px;
    }
}
/* =========================================================
   Reusable inner-page components
   ========================================================= */

.page-banner {
    min-height: 320px;
    padding: 80px 0;
    display: grid;
    place-items: center;
    text-align: center;
    isolation: isolate
}

.page-banner .container {
    position: relative;
    z-index: 2
}

.page-banner-art {
    position: absolute;
    z-index: 0;
    width: 614px;
    height: 400px;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    object-fit: contain;
    opacity: .34;
    pointer-events: none
}

.page-banner h1 {
    font-size: clamp(42px, 4vw, 55px) !important
}

.page-banner p {
    line-height: 2
}

.gradient-divider {
    display: block;
    width: 200px;
    height: 2px;
    margin: 28px auto 20px;
    border-radius: 100px;
    background: linear-gradient(90deg, var(--blue) 0%, var(--pink) 50%, var(--purple) 100%)
}

.section-heading-left {
    margin-bottom: 28px;
    text-align: left
}

.section-heading-left h2 {
    display: block
}

.section-heading-left img {
    width: 155px;
    height: 18px;
    margin: 2px 0 0;
    object-fit: contain
}

.section-heading-left img.stroke-wide {
    width: 225px
}

.content-split {
    position: relative;
    overflow: hidden
}

.content-split > .container,
.decorative-left > .container,
.pattern-right > .container {
    position: relative;
    z-index: 1
}

.content-copy > p {
    line-height: 2
}

.content-copy .theme-btn {
    margin-top: 32px
}

.content-media {
    overflow: hidden;
    border-radius: var(--radius)
}

.content-media img {
    width: 100%;
    object-fit: cover
}

.content-media-wide img {
    height: 370px
}

.content-figure {
    margin: 0
}

.content-figure img {
    width: 100%;
    height: 251px;
    border-radius: var(--radius);
    object-fit: cover
}

.content-figure figcaption {
    margin-top: 20px;
    color: var(--heading);
    font-size: 20px;
    line-height: 1.6;
    font-weight: 500
}

.pattern-right {
    position: relative;
    overflow: hidden
}

.pattern-right::after {
    content: "";
    position: absolute;
    width: 400px;
    height: 414px;
    right: 0;
    top: 0;
    background: url('assets/assets/hosting-an-event.png') center/contain no-repeat;
    pointer-events: none
}

.team-section {
    overflow: hidden
}

.team-section .section-heading {
    margin-bottom: 52px
}

.team-scroller {
    width: 100%;
    overflow-x: auto;
    padding: 0 20px 10px max(20px, calc((100vw - var(--container)) / 2));
    scrollbar-width: none;
    scroll-snap-type: x proximity
}

.team-scroller::-webkit-scrollbar {
    display: none
}

.team-track {
    display: flex;
    gap: 20px;
    width: max-content
}

.team-card {
    width: 387px;
    min-height: 500px;
    padding: 8px;
    flex: 0 0 auto;
    scroll-snap-align: start;
    background: var(--white);
    border-radius: var(--radius);
    box-shadow: 0 0 4px rgba(0, 0, 0, .25)
}

.team-card-image {
    height: 200px;
    overflow: hidden;
    border-radius: var(--radius)
}

.team-card-image img {
    width: 100%;
    height: 100%;
    object-fit: cover
}

.team-card-content {
    padding: 14px 12px 20px
}

.team-card-header {
    margin-bottom: 12px
}

.team-card h3 {
    color: #333;
    font-family: var(--font-body);
    font-size: 20px !important;
    line-height: 1.6;
    font-weight: 500
}

.team-role {
    color: var(--blue);
    line-height: 2;
    font-weight: 500
}

.team-description {
    color: #333;
    line-height: 2;
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 5;
    overflow: hidden
}

.feature-cta {
    min-height: 184px;
    padding: 31px 39px;
    border: 1px solid var(--pink);
    border-radius: 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 40px
}

.feature-cta-copy {
    display: flex;
    align-items: center;
    gap: 20px
}

.feature-cta-copy > img {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    flex: 0 0 auto
}

.feature-cta h2 {
    color: var(--black)
}

@media(max-width:1023px) {
    .page-banner {
        min-height: 290px;
        padding: 65px 0
    }

    .content-split .container {
        grid-template-columns: 1fr
    }

    .content-media {
        max-width: 700px
    }

    .content-media-wide img {
        height: auto
    }

    .content-figure {
        max-width: 520px
    }

    .team-card {
        width: 360px
    }

    .feature-cta {
        align-items: flex-start
    }

    .feature-cta-copy h2 br {
        display: none
    }
}

