    }

    .puppet-benefit-card > img {
        width: 44px;
        height: 44px
    }

    .character-card-copy h3,
    .puppet-program-card h3 {
        font-size: 20px !important
    }

    .performance-info-card {
        padding: 20px;
        min-height: 0
    }

    .puppet-contact-images {
        grid-template-columns: 1fr
    }
}

/* Hand-drawn heading underline used on the Puppets Arts page. */
.puppets-stroke {
    display: block;
    width: 222px;
    height: 16px;
    margin-top: 2px;
    position: relative
}

.emily-heading .section-heading .puppets-stroke {
    margin-left: calc(50% + 145px);
    transform: translateX(-50%)
}

@media(max-width:767px) {
    .puppets-stroke {
        width: 180px
    }

    .emily-heading .section-heading .puppets-stroke {
        margin-left: calc(50% + 90px)
    }
}

